  for(let i=0;i<=4;i++){
   const v=floor+range*i/4,yy=y(v);
   grid+=`<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#dfe8ec" stroke-dasharray="3 4"/><text class="ra833-axis" x="${L-10}" y="${yy+4}" text-anchor="end">${(v*100).toFixed(2)}%</text>`;
  }
