   const y0=e.start.getFullYear(),y1=e.end.getFullYear(),data=[];
   for(let y=y0;y<=y1;y++){let active=0,fail=0,exp=0;const ys=new Date(y,0,1),ye=new Date(y+1,0,1);for(const x of r.rows){const cs=parseDate(x.commissioned),oe=parseDate(x.observed);if(!cs||!oe)continue;const a=new Date(Math.max(+cs,+ys)),b=new Date(Math.min(+oe,+ye));if(b>a){active++;exp+=(b-a)/(365.25*24*3600*1000)}if(x.event&&oe>=ys&&oe<ye)fail++}data.push({y,active,fail,exp})}
   const W=700,H=238,L=58,R=58,T=25,B=42,maxA=Math.max(1,...data.map(d=>d.active)),maxF=Math.max(1,...data.map(d=>d.fail));let bars='',line='',hov='',ticks='';
